import{_ as e,o as l,c as d,a2 as o}from"./chunks/framework.BWuWLRhz.js";const h=JSON.parse('{"title":"热键与交互手势","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/user-guide/hotkeys.md","filePath":"zh-CN/user-guide/hotkeys.md","lastUpdated":1788508383000}'),a={name:"zh-CN/user-guide/hotkeys.md"};function r(n,t,s,i,g,c){return l(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="热键与交互手势" tabindex="-1">热键与交互手势 <a class="header-anchor" href="#热键与交互手势" aria-label="Permalink to &quot;热键与交互手势&quot;">​</a></h1><p>Lertaro 采用键盘优先的交互设计，同时提供极其丰富的鼠标快捷手势与多级导航系统。除固定按键外，所有全局与应用内快捷键均可在<a href="./settings/hotkeys-page.html"><strong>设置 → 热键</strong></a>中自由重新绑定。</p><h2 id="_1-全局快捷键速查表" tabindex="-1">1. 全局快捷键速查表 <a class="header-anchor" href="#_1-全局快捷键速查表" aria-label="Permalink to &quot;1. 全局快捷键速查表&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">功能动作</th><th style="text-align:left;">默认快捷键</th><th style="text-align:left;">功能说明与交互细节</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>呼出/隐藏快速窗口</strong></td><td style="text-align:left;">双击 <code>Ctrl</code></td><td style="text-align:left;">可设置为双击模式或常规组合键（例如 <code>Alt+Space</code>、<code>Win+Space</code> 等）。启用“默认打开完整面板”后，该快捷键会改为打开完整窗口：首次显示时只将其置于前台并聚焦一次，窗口已显示但未激活时重新激活，窗口已经激活时再次按下则关闭；不会自动保持置顶。</td></tr><tr><td style="text-align:left;"><strong>快速切换（Quick Jump）</strong></td><td style="text-align:left;"><code>Ctrl+G</code></td><td style="text-align:left;">在文件对话框中直接跳转到最近一次从受支持文件管理器或快速面板中浏览的文件夹。</td></tr><tr><td style="text-align:left;"><strong>选中下一项</strong></td><td style="text-align:left;"><code>Ctrl+N</code> 或 <code>↓</code></td><td style="text-align:left;">向下移动列表高亮项。在快速面板中支持无缝跨分组连续浏览；在快速启动面板中，方向键按照可见网格移动，左右键会跨越行边界，上下键会在相邻方向寻找最近的同列项目，也会跨越分组；只有相邻方向中整列都没有项目时才保持当前位置；快速启动面板显示且搜索内容为空时，<code>Ctrl+N</code> 会循环切换到下一个数据源。</td></tr><tr><td style="text-align:left;"><strong>选中上一项</strong></td><td style="text-align:left;"><code>Ctrl+P</code> 或 <code>↑</code></td><td style="text-align:left;">向上移动列表高亮项。在快速面板中同样支持跨分组遍历；在快速启动面板中，方向键按照可见网格移动，左右键会跨越行边界，上下键会在相邻方向寻找最近的同列项目，也会跨越分组；只有相邻方向中整列都没有项目时才保持当前位置；快速启动面板显示且搜索内容为空时，<code>Ctrl+P</code> 会循环切换到上一个数据源。</td></tr><tr><td style="text-align:left;"><strong>跳转至第 1–9 项结果</strong></td><td style="text-align:left;"><code>Ctrl</code> + <code>1</code>–<code>9</code></td><td style="text-align:left;">修饰键可自定义，快速窗口结果旁会显示对应的数字徽章，直接按键秒开目标项。</td></tr><tr><td style="text-align:left;"><strong>打开动作菜单</strong></td><td style="text-align:left;"><code>Ctrl+O</code> 或 <code>→</code></td><td style="text-align:left;">展开选中结果的上下文动作面板（复制路径、属性、管理员运行、文件操作等）。</td></tr><tr><td style="text-align:left;"><strong>从选中项补全搜索词</strong></td><td style="text-align:left;"><code>Ctrl+Tab</code></td><td style="text-align:left;">将当前选中项的名称或完整路径直接填入搜索框，便于在此基础上做二次筛选。</td></tr><tr><td style="text-align:left;"><strong>QuickLook 即时预览</strong></td><td style="text-align:left;"><code>Alt+P</code></td><td style="text-align:left;">开启/关闭选中项的侧边预览面板（图片、文档、音视频即时播放、文件夹结构等）。</td></tr><tr><td style="text-align:left;"><strong>上一条搜索历史词</strong></td><td style="text-align:left;"><code>Alt+Up</code></td><td style="text-align:left;">向前翻阅最近输入过的搜索关键词。</td></tr><tr><td style="text-align:left;"><strong>下一条搜索历史词</strong></td><td style="text-align:left;"><code>Alt+Down</code></td><td style="text-align:left;">向后翻阅最近输入过的搜索关键词。</td></tr><tr><td style="text-align:left;"><strong>删除当前历史词</strong></td><td style="text-align:left;"><code>Ctrl+Delete</code></td><td style="text-align:left;">从最近搜索历史记录中移除当前显示的这一条词汇。</td></tr><tr><td style="text-align:left;"><strong>打开完整搜索主窗口</strong></td><td style="text-align:left;"><code>Ctrl+F</code></td><td style="text-align:left;">直接打开大尺寸主搜索窗口，并自动同步当前快速窗口中的搜索词。</td></tr><tr><td style="text-align:left;"><strong>打开发送窗口（LocalSend）</strong></td><td style="text-align:left;"><code>Ctrl+S</code></td><td style="text-align:left;">打开 LocalSend 无线局域网传输窗口，快速发送文件或文本至跨平台设备。</td></tr><tr><td style="text-align:left;"><strong>保持窗口不消失（钉住）</strong></td><td style="text-align:left;"><code>Ctrl+T</code></td><td style="text-align:left;">临时锁定窗口，在失去焦点时不再自动隐藏（便于从其他窗口复制文字组合查询）。</td></tr><tr><td style="text-align:left;"><strong>呼出/关闭快速面板</strong></td><td style="text-align:left;"><code>Ctrl+F2</code></td><td style="text-align:left;">在当前前台活动窗口旁展开包含最近文件、收藏夹、工作区的快速停靠面板。</td></tr></tbody></table><h2 id="_2-搜索框图标与鼠标手势" tabindex="-1">2. 搜索框图标与鼠标手势 <a class="header-anchor" href="#_2-搜索框图标与鼠标手势" aria-label="Permalink to &quot;2. 搜索框图标与鼠标手势&quot;">​</a></h2><p>搜索框内的小图标不仅是品牌标识，更集成了多种实用的鼠标快捷手势：</p><h3 id="快速搜索窗口中的图标手势" tabindex="-1">快速搜索窗口中的图标手势 <a class="header-anchor" href="#快速搜索窗口中的图标手势" aria-label="Permalink to &quot;快速搜索窗口中的图标手势&quot;">​</a></h3><ul><li><strong>鼠标左键单击</strong>：直接在光标处弹出快捷主菜单（显示主窗口、切换热键配置、打开设置、关于、干净退出、退出程序）。其中“显示主窗口”会自动携带当前输入的内容。</li><li><strong>鼠标左键按住拖动</strong>：自由拖动调整搜索栏在屏幕上的显示位置。<strong>拖动时按住 <code>Ctrl</code> 键</strong>可将移动方向严格锁定为<strong>纯垂直方向</strong>，避免水平位置发生偏移。</li><li><strong>鼠标右键单击</strong>：一键将快速窗口重置回屏幕初始默认居中位置（不改变已配置的窗口尺寸）。</li><li><strong>鼠标中键单击</strong>：快捷切换窗口“钉住（保持不消失）”状态，钉住期间 Logo 图标会高亮发光。</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>快速窗口记录的屏幕坐标是相对于所在显示器的<strong>相对比例坐标</strong>。当你将窗口唤出在另一台不同分辨率、不同 DPI 缩放的显示器上时，Lertaro 会自动等比换算位置，绝不会跑出屏幕可视区域。</p></div><h3 id="内嵌窗口与主窗口中的图标" tabindex="-1">内嵌窗口与主窗口中的图标 <a class="header-anchor" href="#内嵌窗口与主窗口中的图标" aria-label="Permalink to &quot;内嵌窗口与主窗口中的图标&quot;">​</a></h3><ul><li><strong>内嵌窗口</strong>：当嵌入在原生文件对话框（打开/保存/浏览）时，左键点击图标可直接展开<a href="#3-快速导航鼠标触发"><strong>快速导航</strong></a>级联菜单；停靠在普通资源管理器时仅作展示。</li><li><strong>主窗口</strong>：鼠标左键点击图标会打开上下文菜单；由于完整窗口已经打开，菜单中的“显示主窗口”项目会隐藏。鼠标中键点击可切换窗口的置顶状态。</li></ul><h2 id="_3-快速导航-鼠标触发" tabindex="-1">3. 快速导航（鼠标触发） <a class="header-anchor" href="#_3-快速导航-鼠标触发" aria-label="Permalink to &quot;3. 快速导航（鼠标触发）&quot;">​</a></h2><p>快速导航功能让你无需打字，通过鼠标点击即可在任意窗口中直达常用目录或打开文件。</p><h3 id="触发方式与支持环境" tabindex="-1">触发方式与支持环境 <a class="header-anchor" href="#触发方式与支持环境" aria-label="Permalink to &quot;触发方式与支持环境&quot;">​</a></h3><ul><li><strong>桌面空白处</strong>：鼠标中键单击（或开启双击左键）直接弹出快速导航菜单，点击目录或文件直接打开。</li><li><strong>文件资源管理器</strong>：在资源管理器空白处点击鼠标中键触发，点击目标后当前窗口立即跳转到该路径。</li><li><strong>第三方文件管理器</strong>：在 Directory Opus、Total Commander、XYplorer、Files、One Commander 等工具的文件列表区点击鼠标中键触发（详见<a href="./file-manager-support.html"><strong>支持的文件管理器</strong></a>）。</li><li><strong>系统文件对话框</strong>：在任意软件的“打开/保存/浏览文件夹”对话框中点击中键或点击内嵌图标触发，点击后对话框直接跳转至目标目录，绝不会误触发“保存/打开”确认。</li></ul><h3 id="级联菜单内容与管理" tabindex="-1">级联菜单内容与管理 <a class="header-anchor" href="#级联菜单内容与管理" aria-label="Permalink to &quot;级联菜单内容与管理&quot;">​</a></h3><p>快速导航菜单由**级联文件夹浏览器（Folder Cascader）**插件驱动，内容高度结构化：</p><ol><li><strong>当前打开的文件夹</strong>：自动汇总并去重所有受支持文件管理器当前正在浏览的真实目录，方便在不同应用间快速同步路径。</li><li><strong>收藏夹与历史记录</strong>：自动按分类列出你的加星收藏与最近访问历史。</li><li><strong>自定义快捷分类</strong>：支持在<strong>设置 → 插件 → 级联文件夹浏览器</strong>中自定义目录与子菜单（如使用 <code>工作/项目A</code> 创建多级分类）。</li><li><strong>一键添加目录（<code>+</code> 按钮）</strong>：菜单每个层级的标题右侧均设有一个 <code>+</code> 按钮，点击即可直接将当前正在浏览的文件夹快速保存到该分类下，无需打开设置面板。</li></ol><h2 id="_4-硬编码核心按键-不可修改" tabindex="-1">4. 硬编码核心按键（不可修改） <a class="header-anchor" href="#_4-硬编码核心按键-不可修改" aria-label="Permalink to &quot;4. 硬编码核心按键（不可修改）&quot;">​</a></h2><p>为了保证最核心交互的确定性与一致性，以下按键在任何配置下行为始终保持统一：</p><table tabindex="0"><thead><tr><th style="text-align:left;">按键</th><th style="text-align:left;">触发场景</th><th style="text-align:left;">统一行为</th></tr></thead><tbody><tr><td style="text-align:left;"><code>Enter</code></td><td style="text-align:left;">结果列表</td><td style="text-align:left;">直接打开选中的结果（文件/目录/程序/动作）。</td></tr><tr><td style="text-align:left;"><code>Ctrl+Enter</code></td><td style="text-align:left;">结果列表</td><td style="text-align:left;">在文件资源管理器中打开并定位选中项所在目录。</td></tr><tr><td style="text-align:left;"><code>Ctrl+Shift+Enter</code></td><td style="text-align:left;">结果列表</td><td style="text-align:left;">以管理员权限启动选中的程序或文件。</td></tr><tr><td style="text-align:left;"><code>Escape</code></td><td style="text-align:left;">任意场景</td><td style="text-align:left;">若搜索框内有文字则清空文字；若搜索框已为空则关闭当前窗口或退出动作菜单。</td></tr><tr><td style="text-align:left;"><code>Backspace</code></td><td style="text-align:left;">动作菜单</td><td style="text-align:left;">当搜索过滤词已为空时，按下直接退出动作菜单返回结果列表。</td></tr><tr><td style="text-align:left;"><code>←</code> / <code>→</code> 方向键</td><td style="text-align:left;">动作菜单</td><td style="text-align:left;">左箭头返回上一级菜单，右箭头进入子菜单。</td></tr><tr><td style="text-align:left;"><code>Alt+Space</code></td><td style="text-align:left;">所有 Lertaro 窗口</td><td style="text-align:left;">强制屏蔽系统标题栏菜单，防止误触弹窗。</td></tr><tr><td style="text-align:left;"><code>Alt+F4</code></td><td style="text-align:left;">主窗口 / 设置窗口</td><td style="text-align:left;">关闭当前窗口。在快速窗口、内嵌窗口及预览浮窗上会被屏蔽（防止误关闭驻留服务）。</td></tr></tbody></table><h2 id="_5-插件动作热键与进程黑名单" tabindex="-1">5. 插件动作热键与进程黑名单 <a class="header-anchor" href="#_5-插件动作热键与进程黑名单" aria-label="Permalink to &quot;5. 插件动作热键与进程黑名单&quot;">​</a></h2><h3 id="插件独立动作热键" tabindex="-1">插件独立动作热键 <a class="header-anchor" href="#插件独立动作热键" aria-label="Permalink to &quot;插件独立动作热键&quot;">​</a></h3><p>插件可以注册专属动作快捷键（例如 <code>Ctrl+Shift+C</code> 快速复制路径，以及内置文件操作：剪切 <code>Ctrl+X</code>、复制 <code>Ctrl+C</code>、粘贴 <code>Ctrl+V</code>、删除 <code>Delete</code>、彻底删除 <code>Shift+Delete</code> 等）。你可以在<strong>设置 → 热键 → 插件动作</strong>中统一查看并重新绑定。</p><h3 id="进程黑名单与全屏自动放行" tabindex="-1">进程黑名单与全屏自动放行 <a class="header-anchor" href="#进程黑名单与全屏自动放行" aria-label="Permalink to &quot;进程黑名单与全屏自动放行&quot;">​</a></h3><ul><li><strong>全屏应用自动放行</strong>：当检测到前台有独占全屏运行的应用程序（如全屏 3D 游戏、全屏视频播放器）时，Lertaro 默认会自动放行所有全局快捷键，绝不抢占游戏控制。</li><li><strong>自定义进程黑名单</strong>：在<a href="./settings/hotkeys-page.html#进程黑名单"><strong>设置 → 热键页面</strong></a>中添加特定进程名（如 <code>game.exe</code>），当该程序处于前台时，全局热键与鼠标快速导航将完全静默放行。</li></ul>',26)])])}const x=e(a,[["render",r]]);export{h as __pageData,x as default};
